def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != bg)
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg:
            out[r0][c] = 2
        if out[r1][c] == bg:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if out[r][c0] == bg:
            out[r][c0] = 2
        if out[r][c1] == bg:
            out[r][c1] = 2
    return out
